INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note) VALUES ('scoa_common_sense', '社会', NULL, '一年を通して気温が高く、降水量も多い、赤道付近に広がる気候はどれか。', NULL, '["砂漠気候","熱帯雨林気候","冷帯気候","ツンドラ気候","地中海性気候"]', 1, '["熱帯雨林気候は赤道付近に分布し、一年を通じて気温が高く、降水量も非常に多いことが特徴で、密林(熱帯雨林)が広がる。"]', 3, 'published', 'ユーザー提供のオリジナル問題（SCOA常識分野: 社会・地理）');
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note) VALUES ('scoa_common_sense', '社会', NULL, '日本の中部地方に連なる、飛驒山脈・木曽山脈・赤石山脈からなる標高3000m級の山々をまとめて何と呼ぶか。', NULL, '["奥羽山脈","日本アルプス","中国山地","紀伊山地","九州山地"]', 1, '["飛驒山脈・木曽山脈・赤石山脈をまとめて日本アルプスと呼び、標高3000m前後の高峰が連なっている。"]', 3, 'published', 'ユーザー提供のオリジナル問題（SCOA常識分野: 社会・地理）');
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note) VALUES ('scoa_common_sense', '社会', NULL, '川が山地から平地に出るところで、土砂が扇状に堆積してできる地形を何というか。', NULL, '["三角州","扇状地","台地","リアス海岸","カルデラ"]', 1, '["扇状地は、川が山地から平地に出る場所で流れが急に緩やかになり、運んできた土砂が扇形に堆積してできる地形である。"]', 3, 'published', 'ユーザー提供のオリジナル問題（SCOA常識分野: 社会・地理）');
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note) VALUES ('scoa_common_sense', '社会', NULL, '夏に乾燥して晴天が多く、冬に雨が多く降るという特徴をもつ気候はどれか。', NULL, '["西岸海洋性気候","地中海性気候","サバナ気候","ステップ気候","亜寒帯気候"]', 1, '["地中海性気候は、夏は高気圧の影響で乾燥し晴天が多く、冬は比較的雨が多く降るという特徴をもつ。地中海沿岸などに分布する。"]', 3, 'published', 'ユーザー提供のオリジナル問題（SCOA常識分野: 社会・地理）');
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note) VALUES ('scoa_common_sense', '社会', NULL, '面積が世界最大の国はどこか。', NULL, '["カナダ","中国","アメリカ合衆国","ロシア","ブラジル"]', 3, '["ロシアはユーラシア大陸北部に広がる世界最大の面積をもつ国で、2位のカナダを大きく上回る国土面積を有する。"]', 3, 'published', 'ユーザー提供のオリジナル問題（SCOA常識分野: 社会・地理）');
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note) VALUES ('scoa_common_sense', '社会', NULL, 'アフリカ大陸北部に広がる、世界最大級の面積をもつ砂漠はどれか。', NULL, '["ゴビ砂漠","カラハリ砂漠","サハラ砂漠","アタカマ砂漠","タクラマカン砂漠"]', 2, '["サハラ砂漠はアフリカ大陸北部に広がる、世界最大級の面積をもつ砂漠である。"]', 3, 'published', 'ユーザー提供のオリジナル問題（SCOA常識分野: 社会・地理）');
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note) VALUES ('scoa_common_sense', '社会', NULL, 'アジア大陸南部を東西に走り、世界最高峰のエベレストを含む山脈はどれか。', NULL, '["アンデス山脈","ロッキー山脈","アルプス山脈","ヒマラヤ山脈","ウラル山脈"]', 3, '["ヒマラヤ山脈はアジア大陸南部に位置し、世界最高峰のエベレスト(チョモランマ)を含む、アルプス・ヒマラヤ造山帯に属する山脈である。"]', 3, 'published', 'ユーザー提供のオリジナル問題（SCOA常識分野: 社会・地理）');
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note) VALUES ('scoa_common_sense', '社会', NULL, '山地が海に沈み込んでできた、入り江と岬が複雑に入り組んだ海岸地形を何というか。', NULL, '["砂浜海岸","リアス海岸","サンゴ礁海岸","三角州海岸","海岸段丘"]', 1, '["リアス海岸は、山地が沈降し海水が谷に入り込むことで、入り江と岬が複雑に入り組んだ海岸線となった地形である。日本では三陸海岸などが代表例。"]', 3, 'published', 'ユーザー提供のオリジナル問題（SCOA常識分野: 社会・地理）');
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note) VALUES ('scoa_common_sense', '社会', NULL, '沿岸国が漁業資源や海底資源を利用する権利を持つ、海岸線から200海里までの水域を何というか。', NULL, '["領海","公海","排他的経済水域","接続水域","大陸棚"]', 2, '["排他的経済水域(EEZ)は、沿岸国が海岸線(基線)から200海里までの範囲で、水産資源や海底資源を優先的に利用できる権利が認められた水域である。"]', 3, 'published', 'ユーザー提供のオリジナル問題（SCOA常識分野: 社会・地理）');
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note) VALUES ('scoa_common_sense', '社会', NULL, '世界の6大陸の中で、人口が最も多い大陸はどこか。', NULL, '["アフリカ","ヨーロッパ","アジア","南アメリカ","北アメリカ"]', 2, '["アジア大陸は中国やインドをはじめとする人口大国を多く含み、世界の6大陸の中で最も人口が多い大陸である。"]', 3, 'published', 'ユーザー提供のオリジナル問題（SCOA常識分野: 社会・地理）');
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note) VALUES ('scoa_common_sense', '社会', NULL, '645年、中大兄皇子と中臣鎌足らが蘇我氏を倒して行った政治改革を何というか。', NULL, '["大宝律令の制定","大化の改新","建武の新政","承久の乱","応仁の乱"]', 1, '["大化の改新は、645年に中大兄皇子と中臣鎌足らが蘇我氏を倒し、天皇を中心とする中央集権的な国家づくりを目指して進めた政治改革である。"]', 3, 'published', 'ユーザー提供のオリジナル問題（SCOA常識分野: 社会・歴史）');
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note) VALUES ('scoa_common_sense', '社会', NULL, '710年、奈良盆地に唐の都・長安にならって造られた都はどれか。', NULL, '["平安京","藤原京","平城京","難波宮","大津宮"]', 2, '["平城京は710年に奈良に置かれた都で、唐の都・長安をモデルに造られ、以後の奈良時代の中心となった。"]', 3, 'published', 'ユーザー提供のオリジナル問題（SCOA常識分野: 社会・歴史）');
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note) VALUES ('scoa_common_sense', '社会', NULL, '鎌倉時代に、モンゴル帝国(元)の軍勢が二度にわたって日本に襲来した出来事を何というか。', NULL, '["元寇","応仁の乱","文永・弘安の平和条約","承久の乱","保元の乱"]', 0, '["元寇は、文永の役(1274年)と弘安の役(1281年)の二度にわたり、元軍が九州北部に襲来した出来事で、武士たちの抵抗や暴風雨などにより退けられた。"]', 3, 'published', 'ユーザー提供のオリジナル問題（SCOA常識分野: 社会・歴史）');
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note) VALUES ('scoa_common_sense', '社会', NULL, '1467年に始まり、室町幕府の権威を大きく低下させ、戦国時代のきっかけとなった大規模な戦乱を何というか。', NULL, '["応仁の乱","承久の乱","保元の乱","壬申の乱","関ヶ原の戦い"]', 0, '["応仁の乱は1467年に始まった約11年に及ぶ大規模な戦乱で、京都を中心に諸大名を巻き込み、室町幕府の権威を大きく低下させ、戦国時代の幕開けとなった。"]', 3, 'published', 'ユーザー提供のオリジナル問題（SCOA常識分野: 社会・歴史）');
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note) VALUES ('scoa_common_sense', '社会', NULL, '江戸幕府が大名に対し、領地と江戸を1年おきに往復させ、江戸に妻子を住まわせた制度の主な目的は何か。', NULL, '["大名の経済力を強化するため","大名の経済力を弱め、幕府への反乱を防ぐため","街道の整備を進めるため","外国との貿易を促進するため","年貢の徴収を効率化するため"]', 1, '["参勤交代は、大名に江戸と領地を往復させることで多額の費用を負担させ、経済力を弱めることで幕府への反乱を防ぐ狙いがあったとされる。"]', 3, 'published', 'ユーザー提供のオリジナル問題（SCOA常識分野: 社会・歴史）');
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note) VALUES ('scoa_common_sense', '社会', NULL, '1853年、浦賀に来航して日本に開国を要求したアメリカの人物は誰か。', NULL, '["ハリス","ペリー","リンカーン","ワシントン","マッカーサー"]', 1, '["1853年、アメリカのペリーが軍艦(黒船)を率いて浦賀に来航し、日本に開国を要求した。これをきっかけに翌年、日米和親条約が結ばれた。"]', 3, 'published', 'ユーザー提供のオリジナル問題（SCOA常識分野: 社会・歴史）');
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note) VALUES ('scoa_common_sense', '社会', NULL, '1871年、それまでの藩を廃止し、新たに府や県を置いて中央集権化を進めた政策を何というか。', NULL, '["版籍奉還","廃藩置県","地租改正","殖産興業","徴兵令"]', 1, '["廃藩置県は1871年に行われ、それまでの藩を廃止して府県を置き、中央から派遣された官吏が地方を治める中央集権体制を確立した。"]', 3, 'published', 'ユーザー提供のオリジナル問題（SCOA常識分野: 社会・歴史）');
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note) VALUES ('scoa_common_sense', '社会', NULL, '1904年に始まり、日本がロシアに勝利したことで国際的地位を高めることになった戦争はどれか。', NULL, '["日清戦争","日露戦争","第一次世界大戦","満州事変","日中戦争"]', 1, '["日露戦争(1904〜1905年)は日本とロシアの間で起こった戦争で、日本が勝利したことにより国際的な地位を高めるきっかけとなった。"]', 3, 'published', 'ユーザー提供のオリジナル問題（SCOA常識分野: 社会・歴史）');
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note) VALUES ('scoa_common_sense', '社会', NULL, '1945年8月、日本が受け入れて無条件降伏を行うきっかけとなった、連合国側が発表した宣言はどれか。', NULL, '["大西洋憲章","ポツダム宣言","カイロ宣言","ヤルタ協定","サンフランシスコ宣言"]', 1, '["ポツダム宣言は1945年7月に連合国側が発表した、日本に無条件降伏を求める宣言であり、日本は同年8月にこれを受け入れて終戦を迎えた。"]', 3, 'published', 'ユーザー提供のオリジナル問題（SCOA常識分野: 社会・歴史）');
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note) VALUES ('scoa_common_sense', '社会', NULL, '1951年に結ばれ、日本が独立を回復するきっかけとなった条約はどれか。', NULL, '["日米安全保障条約","サンフランシスコ平和条約","日中平和友好条約","日ソ共同宣言","下関条約"]', 1, '["サンフランシスコ平和条約は1951年に結ばれ、翌1952年に発効したことで、日本は連合国軍の占領から独立を回復した。"]', 3, 'published', 'ユーザー提供のオリジナル問題（SCOA常識分野: 社会・歴史）');
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note) VALUES ('scoa_common_sense', '社会', NULL, '最高裁判所の裁判官が適任であるかどうかを、国民の投票によって審査する制度を何というか。', NULL, '["弾劾裁判","国民審査","違憲審査","住民投票","国政調査"]', 1, '["国民審査は、最高裁判所の裁判官が任命後初めて行われる衆議院議員総選挙の際などに、その裁判官がふさわしいかどうかを国民の投票によって審査する制度である。"]', 3, 'published', 'ユーザー提供のオリジナル問題（SCOA常識分野: 社会・政治）');
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note) VALUES ('scoa_common_sense', '社会', NULL, '日本国憲法の改正を国会が発議するために必要な、各議院における賛成の割合として正しいものはどれか。', NULL, '["各議院の出席議員の過半数","各議院の総議員の過半数","各議院の総議員の3分の2以上","衆議院のみ総議員の3分の2以上","両議院を合わせた議員の過半数"]', 2, '["憲法改正の発議には、衆議院・参議院それぞれの総議員の3分の2以上の賛成が必要であり、その後国民投票で過半数の賛成を得ることで改正が成立する。"]', 3, 'published', 'ユーザー提供のオリジナル問題（SCOA常識分野: 社会・政治）');
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note) VALUES ('scoa_common_sense', '社会', NULL, '内閣が衆議院で不信任決議を可決された場合にとりうる対応として正しいものはどれか。', NULL, '["必ず内閣総理大臣が辞職しなければならない","10日以内に衆議院を解散するか、総辞職しなければならない","参議院の解散を行う","何もする必要はない","最高裁判所に意見を求める"]', 1, '["衆議院で内閣不信任決議が可決された場合、内閣は10日以内に衆議院を解散するか、総辞職しなければならないと憲法で定められている。"]', 3, 'published', 'ユーザー提供のオリジナル問題（SCOA常識分野: 社会・政治）');
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note) VALUES ('scoa_common_sense', '社会', NULL, '都道府県知事や市町村長など、地方公共団体の首長はどのように選ばれるか。', NULL, '["地方議会議員による選挙","内閣が任命する","住民による直接選挙","国会の議決による指名","最高裁判所が任命する"]', 2, '["地方公共団体の首長(知事・市町村長)は、その地域の住民による直接選挙によって選ばれる。これは国の内閣総理大臣の選出方法(議院内閣制)とは異なる点である。"]', 3, 'published', 'ユーザー提供のオリジナル問題（SCOA常識分野: 社会・政治）');
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note) VALUES ('scoa_common_sense', '社会', NULL, '法律案が正式に法律として成立するために必要な手続きとして正しいものはどれか。', NULL, '["内閣の承認のみで成立する","衆議院と参議院の両方で可決される必要がある(原則)","最高裁判所の審査を経る必要がある","天皇の発案が必要である","国民投票で過半数の賛成が必要である"]', 1, '["法律案は、原則として衆議院と参議院の両方で可決されることで法律として成立する。両院の議決が異なる場合には、衆議院の優越などの規定が適用される。"]', 3, 'published', 'ユーザー提供のオリジナル問題（SCOA常識分野: 社会・政治）');
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note) VALUES ('scoa_common_sense', '社会', NULL, '日本国憲法が保障する自由権に含まれないものはどれか。', NULL, '["思想・良心の自由","表現の自由","職業選択の自由","生存権","信教の自由"]', 3, '["生存権は「健康で文化的な最低限度の生活を営む権利」であり、国に一定の作為を求める社会権に分類される。思想・良心の自由、表現の自由、職業選択の自由、信教の自由はいずれも国からの干渉を受けない自由権に分類される。"]', 3, 'published', 'ユーザー提供のオリジナル問題（SCOA常識分野: 社会・政治）');
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note) VALUES ('scoa_common_sense', '社会', NULL, '労働者に保障された、団結権・団体交渉権・団体行動権をまとめて何というか。', NULL, '["社会権","労働三権","参政権","自由権","基本的人権"]', 1, '["労働三権(団結権・団体交渉権・団体行動権)は、労働者が使用者と対等な立場で交渉できるよう憲法で保障された権利である。"]', 3, 'published', 'ユーザー提供のオリジナル問題（SCOA常識分野: 社会・政治）');
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note) VALUES ('scoa_common_sense', '社会', NULL, '国民が刑事裁判に参加し、裁判官とともに被告人が有罪か無罪か、有罪の場合の量刑を判断する制度を何というか。', NULL, '["国民審査制度","裁判員制度","検察審査会制度","陪審制度(アメリカ式)","参審制度"]', 1, '["裁判員制度は、くじで選ばれた国民(裁判員)が刑事裁判に参加し、裁判官とともに事実認定や量刑の判断を行う日本独自の制度である。"]', 3, 'published', 'ユーザー提供のオリジナル問題（SCOA常識分野: 社会・政治）');
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note) VALUES ('scoa_common_sense', '社会', NULL, '日本の国会が衆議院と参議院の二院制をとっている主な目的として適切なものはどれか。', NULL, '["審議を迅速に進めるため","一つの議院に権力が集中することを防ぎ、慎重な審議を行うため","地方の意見を無視するため","内閣の権限を強化するため","国民の意見を反映させないため"]', 1, '["二院制は、一つの議院の判断だけに頼らず、異なる任期や選出方法をもつ二つの議院で審議することで、多角的で慎重な議論を行うことを目的としている。"]', 3, 'published', 'ユーザー提供のオリジナル問題（SCOA常識分野: 社会・政治）');
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note) VALUES ('scoa_common_sense', '社会', NULL, '政府から独立し、利益を目的とせずに国内外で社会的な活動を行う民間の団体を何というか。', NULL, '["NGO(非政府組織)","WHO(世界保健機関)","IMF(国際通貨基金)","OECD(経済協力開発機構)","WTO(世界貿易機関)"]', 0, '["NGO(非政府組織)は、政府から独立して活動する民間の非営利団体であり、人道支援や環境保護などさまざまな分野で国内外の活動を行っている。"]', 3, 'published', 'ユーザー提供のオリジナル問題（SCOA常識分野: 社会・政治）');
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note) VALUES ('scoa_common_sense', '社会', NULL, '所得が高くなるほど税率が高くなる課税方式を何というか。', NULL, '["比例課税","累進課税","定額課税","間接課税","逆進課税"]', 1, '["累進課税は所得が高くなるほど税率も高くなる課税方式で、所得税などに採用されており、所得の再分配機能をもつ。"]', 3, 'published', 'ユーザー提供のオリジナル問題（SCOA常識分野: 社会・経済）');
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note) VALUES ('scoa_common_sense', '社会', NULL, '労働者の権利を保護するために定められた、労働基準法・労働組合法・労働関係調整法をまとめて何というか。', NULL, '["労働三権","労働三法","労働基準三原則","社会保障関連法","独占禁止関連法"]', 1, '["労働三法は、労働者の労働条件や権利を保護するために定められた、労働基準法・労働組合法・労働関係調整法の3つの法律の総称である。"]', 3, 'published', 'ユーザー提供のオリジナル問題（SCOA常識分野: 社会・経済）');
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note) VALUES ('scoa_common_sense', '社会', NULL, '企業の公正な自由競争を確保し、市場の独占や不当な取引制限を規制するために制定された法律はどれか。', NULL, '["消費者契約法","独占禁止法","労働基準法","製造物責任法(PL法)","景品表示法"]', 1, '["独占禁止法は、企業による市場の独占や不当なカルテルなどを規制し、公正で自由な競争を確保することを目的とした法律である。"]', 3, 'published', 'ユーザー提供のオリジナル問題（SCOA常識分野: 社会・経済）');
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note) VALUES ('scoa_common_sense', '社会', NULL, '商品やサービスの購入時に、所得の多少にかかわらず同じ税率が課される税の性質を持つものはどれか。', NULL, '["所得税","法人税","消費税","相続税","固定資産税"]', 2, '["消費税は、購入する人の所得にかかわらず同じ税率が課される間接税であり、所得の低い人ほど負担の割合が大きくなる逆進性をもつとされる。"]', 3, 'published', 'ユーザー提供のオリジナル問題（SCOA常識分野: 社会・経済）');
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note) VALUES ('scoa_common_sense', '社会', NULL, '銀行が預金の一部を貸し出しに回し、その貸し出されたお金が再び預金されることで、当初の預金額以上のお金が経済全体に生み出されるしくみを何というか。', NULL, '["信用創造","財政政策","為替介入","公開市場操作","量的緩和"]', 0, '["信用創造は、銀行が預金の一部を貸し出し、そのお金が再び別の銀行に預金されるという流れが繰り返されることで、社会全体の預金通貨(お金の量)が当初の預金額以上に増加していくしくみである。"]', 3, 'published', 'ユーザー提供のオリジナル問題（SCOA常識分野: 社会・経済）');
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note) VALUES ('scoa_common_sense', '社会', NULL, '一国の輸出額が輸入額を上回っている状態を何というか。', NULL, '["貿易赤字","貿易黒字","国際収支の均衡","経常収支の赤字","為替差損"]', 1, '["貿易黒字は、一定期間における輸出額が輸入額を上回っている状態を指す。逆に輸入額が輸出額を上回る状態を貿易赤字という。"]', 3, 'published', 'ユーザー提供のオリジナル問題（SCOA常識分野: 社会・経済）');
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note) VALUES ('scoa_common_sense', '社会', NULL, '日本において紙幣(日本銀行券)を発行し、金融政策を担う中央銀行はどこか。', NULL, '["日本政策金融公庫","日本銀行","財務省","国際通貨基金","みずほ銀行"]', 1, '["日本銀行は日本の中央銀行であり、紙幣(日本銀行券)の発行や物価の安定を図るための金融政策を担う機関である。"]', 3, 'published', 'ユーザー提供のオリジナル問題（SCOA常識分野: 社会・経済）');
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note) VALUES ('scoa_common_sense', '社会', NULL, '好況・後退・不況・回復という局面を繰り返しながら経済活動が周期的に変動することを何というか。', NULL, '["インフレーション","景気循環","経済成長","為替変動","財政赤字"]', 1, '["景気循環は、経済活動が好況・後退・不況・回復といった局面を周期的に繰り返しながら変動していく現象を指す。"]', 3, 'published', 'ユーザー提供のオリジナル問題（SCOA常識分野: 社会・経済）');
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note) VALUES ('scoa_common_sense', '社会', NULL, 'ある商品の需要量が供給量を大きく上回った場合、一般にその商品の価格はどう変化するか。', NULL, '["上昇する","下落する","変化しない","必ず一定になる","供給量に関わらず一定に保たれる"]', 0, '["需要量が供給量を上回ると、商品が品薄になるため、市場では一般に価格が上昇する傾向がある。逆に供給量が需要量を上回ると価格は下落する傾向がある。"]', 3, 'published', 'ユーザー提供のオリジナル問題（SCOA常識分野: 社会・経済）');
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note) VALUES ('scoa_common_sense', '社会', NULL, '税を負担する人と実際に納める人が同じである税を何というか。', NULL, '["間接税","直接税","消費税","関税","地方税のみを指す"]', 1, '["直接税は、税を負担する人(担税者)と実際に税務署などに納める人(納税者)が同一である税で、所得税や法人税などが該当する。一方、消費税のように負担者と納税者が異なる税を間接税という。"]', 3, 'published', 'ユーザー提供のオリジナル問題（SCOA常識分野: 社会・経済）');
